#define DBG(x) cerr<<(#x)<<"="<<x<<"\n";

#define FOREACH(it,x) for(__typeof(x.begin()) it=x.begin();it!=x.end();it++)
#define ull unsigned long long
#define ll long long
#define N 500005

template <class T,class U>inline void Max(T &a,U b){if(a<b)a=b;}
template <class T,class U>inline void Min(T &a,U b){if(a>b)a=b;}

//FILE* outFile;

inline void add(int &a,int b){a+=b;while(a>=mod)a-=mod;}
inline int gcd(int a, int b){if(b == 0)return a; return gcd(b, a%b);}
int pow(int a,int b){
    int ans=1;
    while(b){
        if(b&1)ans=ans*(ll)a%mod;
        a=(ll)a*a%mod;b>>=1;
    }
    return ans;
}

const int M = 105;
int a[51], id[51][M];
pii b[51];
int cnt, head[N], d[N], p[N], vis[N];
struct node{
    int v, c, w, next;
}g[N<<2];
void add(int a, int b, int c, int w){
    g[cnt] = {b, c, w, head[a]}, head[a] = cnt++;
    g[cnt] = {a, 0, -w, head[b]}, head[b] = cnt++;
}
int bfs(int s, int t){
    rep(i, 0, t+1)d[i] = inf, vis[i] = 0;
    queue<int>q;
    q.push(s); d[s] = 0;
    while(!q.empty()){
        int u = q.front(); q.pop(); vis[u] = 0;
        for(int i = head[u]; ~i; i = g[i].next){
            int j = g[i].v;
            if(g[i].c && d[j] > d[u] + g[i].w){
                d[j] = d[u] + g[i].w;
                p[j] = i;
                if(!vis[j]){
                    vis[j] = 1;
                    q.push(j);
                }
            }
        }
    }
    return d[t] < inf;
}
int max_flow(int s, int t){
    int ans = 0, res = 0;
    while(bfs(s, t)){
        int x = t, f = inf;
        while(x != s){
            Min(f, g[p[x]].c), x = g[p[x] ^ 1].v;
        }
        ans += f * d[t];
        res += f;
        x = t;
        while(x != s){
            g[p[x]].c -= f, g[p[x] ^ 1].c += f;
            x = g[p[x] ^ 1].v;
        }
    }
    DBG(res)
    return ans;
}
