    rep(i, 0, M)add(id[0][i], t, K, C * i);
    rep(i, 0, n){
        rep(j, 0, M-1){
            add(id[i][j], id[i][j+1], K, 0);
        }
    }
    rep(i, 0, m){
        int x = b[i].x, y = b[i].y;
        rep(j, 0, M-1){
            rep(k, 0, K){
                add(id[x][j], id[y][j+1], 1, D*(2*k + 1));
                add(id[y][j], id[x][j+1], 1, D*(2*k + 1));
            }
        }
    }
    int ans = max_flow(s, t);
    printf("%d\n", ans);
}

